int is_prime(long long n) {
    if (n < 2) return 0;
    if (n == 2) return 1;
    if (n % 2 == 0) return 0;
    for (long long i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return 0;
    }
    return 1;
}

int is_ginkgo_prime(long long m, long long n) {
    long long N = m * m + n * n;
    if (N <= 1) return 0;
    if (m == 0) {
        long long a = n < 0 ? -n : n;
        return is_prime(a) && (a % 4 == 3);
    }
    if (n == 0) {
        long long a = m < 0 ? -m : m;
        return is_prime(a) && (a % 4 == 3);
    }
    return is_prime(N);
}

