                if (m == 0) {
                    long absn = Math.abs(n);
                    prime = isPrime(absn) && absn % 4 == 3;
                } else if (n == 0) {
                    long absm = Math.abs(m);
                    prime = isPrime(absm) && absm % 4 == 3;
                } else {
                    prime = isPrime(norm);
                }
            }
            System.out.println(prime ? "Prime" : "Not Prime");
        }
    }
