import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        boolean hasNext() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return false;
            } while (c <= ' ');
            ptr--;
            return true;
        }
    }

    static long divisorCount(long x) {
        long cnt = 1;
        for (long p = 2; p * p <= x; p++) {
            if (x % p == 0) {
                int e = 0;
                while (x % p == 0) {
                    x /= p;
                    e++;
                }
                cnt *= (e + 1);
            }
        }
        if (x > 1) cnt *= 2;
        return cnt;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (fs.hasNext()) {
            long m = fs.nextLong();
            if (!fs.hasNext()) break;
            long n = fs.nextLong();

            long s = m * m + n * n;
            boolean primeGinkgo = s > 1 && divisorCount(s) == 8;
            out.append(primeGinkgo ? "Prime" : "Not prime").append('\n');
        }

        System.out.print(out.toString());
    }
}

